insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-age:11-c4144168cd','aux-age',11,'La declaración de incompetencia de un órgano contencioso-administrativo adopta la forma de:','["Sentencia", "Diligencia de ordenación", "Auto", "Providencia"]'::jsonb,2,'Art. 7.3 Ley 29/1998','Se remiten las actuaciones al órgano competente y las partes tienen diez días para comparecer ante él.',null),
('aux-age:11-251b6f2ab4','aux-age',11,'La jurisdicción contencioso-administrativa es:','["Prorrogable por decisión del Gobierno", "Voluntaria", "Prorrogable por acuerdo de las partes", "Improrrogable"]'::jsonb,3,'Art. 5.1 Ley 29/1998','Los órganos apreciarán de oficio la falta de jurisdicción.',null),
('aux-age:11-a6c8db6cbd','aux-age',11,'La Sala de lo Contencioso-administrativo del Tribunal Supremo conoce en única instancia de los recursos contra actos y disposiciones de:','["El Consejo de Ministros", "Los Alcaldes", "Los Delegados del Gobierno", "Los Consejeros de las Comunidades Autónomas"]'::jsonb,0,'Art. 12.1 a) Ley 29/1998','También del CGPJ y del Fiscal General del Estado, entre otros.',null),
('aux-age:14-c2cbf8945e','aux-age',14,'Las pagas extraordinarias de los funcionarios serán:','["Una al año, por el importe de una mensualidad de retribuciones básicas", "Cuatro al año", "Tres al año, cada una por el importe de una mensualidad de retribuciones básicas y de la mitad de las complementarias, que se abonan en marzo, junio y diciembre", "Dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las complementarias, salvo excepciones"]'::jsonb,3,'Art. 22.4 TREBEP','Son dos pagas al año.',null),
('aux-age:16-7fe4e20c89','aux-age',16,'Los proyectos de disposiciones de carácter general y los planes de especial relevancia que se sometan a la aprobación del Consejo de Ministros deberán incorporar:','["Un informe del Consejo de Estado en todo caso", "Un informe sobre su impacto por razón de género", "Un informe económico de la UE", "La firma de todas las Comunidades Autónomas"]'::jsonb,1,'Art. 19 LO 3/2007','Es el informe de impacto de género.',null),
('aux-age:16-9bcdacfd72','aux-age',16,'La suspensión y la extinción del contrato de trabajo de la trabajadora víctima de violencia de género:','["Darán lugar a situación legal de desempleo", "Requieren autorización judicial previa", "No dan derecho a prestación por desempleo, salvo que lo reconozca una sentencia", "Se consideran despido disciplinario"]'::jsonb,0,'Art. 21.2 LO 1/2004','El tiempo de suspensión se considera periodo de cotización efectiva.',null),
('aux-age:13-325095f956','aux-age',13,'La renuncia voluntaria a la condición de funcionario:','["Habrá de ser manifestada por escrito y será aceptada expresamente por la Administración, salvo que el funcionario esté sujeto a expediente disciplinario o procesado", "Puede manifestarse verbalmente ante el superior jerárquico", "No necesita aceptación expresa y surte efectos desde su presentación, aunque el funcionario esté sujeto a expediente disciplinario o haya sido procesado por un delito", "No está permitida mientras el funcionario no haya cumplido la edad de jubilación, salvo que lo autorice expresamente el Consejo de Gobierno por razones excepcionales de interés público"]'::jsonb,0,'Art. 64 TREBEP','La renuncia no inhabilita para volver a ingresar por el procedimiento de selección.',null),
('aux-age:11-98d5184449','aux-age',11,'Los Juzgados de lo Contencioso-administrativo conocen de los recursos contra actos de la Administración autonómica en materia de responsabilidad patrimonial cuya cuantía no exceda de:','["100.000 euros", "60.000 euros", "30.050 euros", "18.000 euros"]'::jsonb,2,'Art. 8.2 c) Ley 29/1998','También de sanciones con multa no superior a 60.000 euros, entre otros supuestos. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('aux-age:13-81e8e79b9e','aux-age',13,'Transcurridos tres años desde el nombramiento de un interino en plaza vacante, esta:','["Solo podrá ser ocupada por personal funcionario de carrera, salvo que el proceso selectivo quede desierto", "Se amortiza automáticamente y el interino cesa sin derecho a indemnización, aunque el proceso selectivo no se haya convocado", "Pasa a ser plaza de personal laboral", "Se convierte automáticamente en plaza en propiedad del interino que la ocupa, sin necesidad de proceso selectivo"]'::jsonb,0,'Art. 10.4 TREBEP','Se produce el fin de la relación de interinidad.',null),
('aux-age:14-aa1facd9bc','aux-age',14,'Es un derecho individual de los empleados públicos del art. 14 TREBEP:','["La formación continua y la actualización permanente de sus conocimientos", "La negociación colectiva y la participación en la determinación de las condiciones de trabajo", "La huelga y el planteamiento de conflictos colectivos de trabajo en su unidad", "El planteamiento de conflictos colectivos de trabajo"]'::jsonb,0,'Art. 14 g) TREBEP','Los demás citados son derechos individuales ejercidos colectivamente (art. 15).',null),
('aux-age:13-d7579da63c','aux-age',13,'Durante los dos primeros años de excedencia por cuidado de hijos o familiares, el funcionario tiene derecho a:','["Ascender automáticamente de grado", "Nada, salvo el cómputo de antigüedad", "La reserva del puesto de trabajo que desempeñaba", "Seguir percibiendo las retribuciones básicas y la reserva de un puesto en la misma localidad"]'::jsonb,2,'Art. 89.4 TREBEP','Transcurrido ese periodo, la reserva lo es a un puesto en la misma localidad y de igual retribución.',null),
('aux-age:14-7115a9d3f7','aux-age',14,'Las sanciones impuestas por faltas graves prescriben a los:','["Un año", "Dos años", "Tres años", "Seis meses"]'::jsonb,1,'Art. 97 TREBEP','Las muy graves a los tres años y las leves al año.',null),
('aux-age:16-1eff82a6ee','aux-age',16,'Las ausencias o faltas de puntualidad al trabajo de la trabajadora víctima de violencia de género motivadas por su situación física o psicológica:','["Se descuentan del sueldo en todo caso, aunque los servicios sociales de atención o de salud acrediten que están motivadas por su situación física o psicológica", "Se considerarán justificadas y serán remuneradas cuando así lo determinen los servicios sociales de atención o de salud", "Requieren autorización judicial", "Serán siempre sancionadas como falta leve, aunque los servicios sociales de atención o de salud acrediten que derivan de su situación"]'::jsonb,1,'Art. 21.4 LO 1/2004','Deben comunicarse a la empresa a la mayor brevedad.',null),
('aux-age:11-2e547be300','aux-age',11,'En caso de inactividad, si la Administración no da cumplimiento a lo reclamado o no llega a un acuerdo con los interesados, estos pueden recurrir si transcurre desde la reclamación un plazo de:','["Seis meses", "Tres meses", "Un mes", "Diez días"]'::jsonb,1,'Art. 29.1 Ley 29/1998','Pasados tres meses desde la reclamación, cabe recurso contra la inactividad.',null),
('aux-age:14-9121edaa58','aux-age',14,'Las faltas muy graves prescriben a los:','["Dos años", "Seis meses", "Cinco años", "Tres años"]'::jsonb,3,'Art. 97 TREBEP','Las graves a los dos años y las leves a los seis meses.',null),
('aux-age:11-9a8c055493','aux-age',11,'El recurso de apelación contra sentencias es admisible, salvo que la ley disponga otra cosa:','["Sin efectos", "En ambos efectos", "Solo en un efecto", "Solo en efecto devolutivo"]'::jsonb,1,'Art. 83.1 Ley 29/1998','La apelación no impide la ejecución provisional de la sentencia (art. 84).',null),
('aux-age:14-1bbac196f1','aux-age',14,'A efectos de vacaciones de los funcionarios, los sábados:','["No se consideran días hábiles, salvo en los horarios especiales", "Computan doble", "Se consideran hábiles solo en agosto", "Se consideran siempre días hábiles, cualquiera que sea el horario del funcionario"]'::jsonb,0,'Art. 50.1 TREBEP','Las vacaciones son de 22 días hábiles.',null),
('aux-age:11-56c2bd2c25','aux-age',11,'La Administración debe remitir el expediente administrativo al juzgado o tribunal en el plazo improrrogable de:','["Un mes natural", "Diez días hábiles desde la reclamación", "Veinte días", "Dos meses"]'::jsonb,2,'Art. 48.3 Ley 29/1998','El expediente se remite en veinte días.',null),
('aux-age:14-5f221a8680','aux-age',14,'La parte de jornada no realizada sin justificación dará lugar a:','["La deducción proporcional de haberes, que no tendrá carácter sancionador", "Ninguna consecuencia económica, aunque deberá recuperarse en otro momento de la semana", "La separación del servicio", "Una sanción disciplinaria grave, previa tramitación del expediente correspondiente"]'::jsonb,0,'Art. 30.1 TREBEP','La deducción no es una sanción.',null),
('aux-age:11-50ce6bdfba','aux-age',11,'En el procedimiento abreviado, el juez dictará sentencia en el plazo de:','["Veinte días", "Un mes desde la presentación de la demanda", "Diez días desde la celebración de la vista", "Cinco días desde la presentación de la demanda"]'::jsonb,2,'Art. 78.20 Ley 29/1998','Se dicta en diez días desde la vista.',null),
('aux-age:14-afc2d00217','aux-age',14,'Para participar en la promoción interna, los funcionarios deben poseer una antigüedad de, al menos:','["Un año de servicio activo en el mismo cuerpo o escala", "Dos años de servicio activo en el inferior subgrupo o grupo de clasificación profesional", "Tres años de servicio activo en el mismo cuerpo o escala, de los cuales al menos uno en la misma Administración", "Cinco años de servicio activo en cualquier cuerpo o escala de la misma Administración pública"]'::jsonb,1,'Art. 18.2 TREBEP','Además de la titulación y demás requisitos exigidos.',null),
('aux-age:16-9aa143ae77','aux-age',16,'Según la LO 3/2007, se considera discriminación por razón de sexo cualquier trato adverso o efecto negativo producido como consecuencia de:','["Su afiliación a un partido político o a un sindicato", "Su cambio de domicilio", "La presentación por una persona de una queja, reclamación, denuncia o demanda destinada a impedir su discriminación", "Su ascenso profesional o la obtención de un puesto de libre designación tras un procedimiento de provisión con convocatoria pública"]'::jsonb,2,'Art. 9 LO 3/2007','Es la garantía de indemnidad frente a represalias.',null),
('aux-age:11-d4dfae416b','aux-age',11,'En caso de vía de hecho, el interesado puede formular requerimiento a la Administración y, si no es atendido en el plazo de:','["Tres meses, podrá interponer recurso de alzada ante el superior jerárquico", "Un mes, podrá interponer recurso de alzada ante el superior jerárquico del órgano", "Diez días, podrá deducir directamente recurso contencioso-administrativo", "Veinte días"]'::jsonb,2,'Art. 30 Ley 29/1998','Si el requerimiento no se formula o no se atiende en diez días, cabe recurso directo.',null),
('aux-age:11-4942a8ca31','aux-age',11,'Las decisiones que adopte el juez sobre cuestiones prejudiciales o incidentales no pertenecientes al orden contencioso-administrativo:','["Deben confirmarse por el Tribunal Supremo", "Vinculan a los tribunales penales", "Producen efectos de cosa juzgada en todos los órdenes", "No producirán efectos fuera del proceso en que se dicten"]'::jsonb,3,'Art. 4.2 Ley 29/1998','Solo producen efectos en el proceso en que se dictan.',null),
('aux-age:13-8e52c71854','aux-age',13,'Durante los dos primeros meses de excedencia por razón de violencia de género, la funcionaria tendrá derecho a:','["No percibir retribución alguna, aunque se le reserva el puesto de trabajo y se computa el tiempo a efectos de antigüedad", "Percibir las retribuciones íntegras y, en su caso, las prestaciones familiares por hijo a cargo", "Percibir el 50 % de sus retribuciones básicas y complementarias", "Percibir solo las retribuciones básicas, pero no las complementarias ni las prestaciones familiares por hijo a cargo"]'::jsonb,1,'Art. 89.5 TREBEP','Durante los seis primeros meses tiene reserva del puesto, prorrogable por periodos de tres meses hasta dieciocho.',null),
('aux-age:11-da4e1fb766','aux-age',11,'Los Juzgados Centrales de lo Contencioso-administrativo conocen, entre otros, de los recursos contra actos de los organismos públicos con competencia en:','["Una Comunidad Autónoma", "Un solo municipio", "Una sola provincia o un solo partido judicial", "Todo el territorio nacional"]'::jsonb,3,'Art. 9.1 c) Ley 29/1998','Conocen en primera o única instancia de los recursos contra disposiciones y actos de esos organismos en los términos del art. 9. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('aux-age:11-09ba520a83','aux-age',11,'Las medidas cautelares podrán acordarse cuando la ejecución del acto o la aplicación de la disposición:','["Pudieran hacer perder su finalidad legítima al recurso, previa valoración de todos los intereses en conflicto", "Lo pida el Ministerio Fiscal o la Administración demandada, sin necesidad de valorar los intereses en conflicto ni la finalidad del recurso", "Haya sido recurrida en alzada o en reposición y no se haya resuelto el recurso", "Cause cualquier molestia o perjuicio al recurrente, aunque no haga perder su finalidad al recurso ni se valoren los intereses en conflicto"]'::jsonb,0,'Art. 130.1 Ley 29/1998','Pueden denegarse si causan perturbación grave de los intereses generales o de tercero.',null),
('aux-age:13-0976050ca7','aux-age',13,'La designación del personal directivo profesional atenderá a principios de:','["Libre designación política por el titular del órgano superior", "Sorteo entre funcionarios del subgrupo A1", "Antigüedad en el cuerpo, y en caso de empate, mérito y capacidad mediante procedimientos que garanticen la publicidad y la concurrencia", "Mérito y capacidad y criterios de idoneidad, mediante procedimientos que garanticen la publicidad y concurrencia"]'::jsonb,3,'Art. 13.2 TREBEP','Así lo establece el art. 13.2.',null),
('aux-age:14-ec9976956d','aux-age',14,'Los trienios consisten en una cantidad, igual para cada subgrupo o grupo, por cada:','["Año de servicio", "Cinco años de servicio", "Dos años de servicio", "Tres años de servicio"]'::jsonb,3,'Art. 23 b) TREBEP','Retribución básica por antigüedad.',null),
('aux-age:11-9997fc2910','aux-age',11,'La sentencia estimará el recurso contencioso-administrativo cuando la disposición o el acto incurran en:','["Defectos de forma que produzcan indefensión, pero no la desviación de poder", "Cualquier infracción del ordenamiento jurídico, incluso la desviación de poder", "Vulneración de derechos fundamentales y libertades públicas susceptibles de amparo constitucional", "Causas de nulidad de pleno derecho, pero no en meros vicios de anulabilidad del acto"]'::jsonb,1,'Art. 70.2 Ley 29/1998','Si se ajusta a Derecho, el recurso se desestima.',null),
('aux-age:14-81c65a72dd','aux-age',14,'Las retribuciones de los funcionarios de carrera se clasifican en:','["Ordinarias y extraordinarias", "Directas e indirectas", "Básicas y complementarias", "Fijas y variables"]'::jsonb,2,'Art. 22.1 TREBEP','Las pagas extraordinarias son dos al año.',null),
('aux-age:14-e4e5318303','aux-age',14,'Los Pactos y Acuerdos, salvo que se establezca otra cosa:','["Se prorrogarán de año en año si no media denuncia expresa de una de las partes", "Caducan al año de su firma, salvo que se renueven expresamente", "Se prorrogarán por periodos de cuatro años, salvo que una de las partes los denuncie con seis meses de antelación", "Duran cuatro años improrrogables"]'::jsonb,0,'Art. 38.11 TREBEP','Prórroga anual salvo denuncia.',null),
('aux-age:14-1488c2f922','aux-age',14,'Por fallecimiento de un familiar de primer grado en la misma localidad, el permiso es de:','["Cinco días hábiles", "Tres días hábiles", "Dos días hábiles", "Un día"]'::jsonb,1,'Art. 48 a) TREBEP','Si es en distinta localidad, cinco días hábiles.',null),
('aux-age:16-928b0ffbbe','aux-age',16,'Los servicios de asistencia social integral a las víctimas de violencia de género responderán, entre otros, a los principios de:','["Gratuidad parcial, voluntariedad, subsidiariedad respecto de los servicios generales y atención exclusiva en horario de oficina", "Secreto, discrecionalidad, gratuidad parcial, subsidiariedad respecto de los servicios generales y atención en horario de oficina", "Centralización y uniformidad", "Atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional"]'::jsonb,3,'Art. 19.1 LO 1/2004','Son los principios de la asistencia social integral.',null),
('aux-age:11-d0dbfd9f22','aux-age',11,'En los recursos con estimación parcial de las pretensiones, como regla general:','["Las paga siempre el recurrente que haya visto rechazada cualquiera de sus pretensiones", "Cada parte abonará las costas causadas a su instancia y las comunes por mitad", "Las paga la parte cuyas pretensiones hayan sido desestimadas en mayor medida, salvo que el órgano aprecie temeridad", "Las paga siempre la Administración demandada"]'::jsonb,1,'Art. 139.1 Ley 29/1998','Salvo que el órgano aprecie mala fe o temeridad en alguna de las partes.',null),
('aux-age:14-ea3b01a1b6','aux-age',14,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["El 10 % de los miembros de los órganos unitarios de representación", "La totalidad de los miembros de los órganos unitarios de representación", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate"]'::jsonb,2,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('aux-age:13-efac4d45c8','aux-age',13,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["Salvo en la Administración Local, cuando lo acuerde el Pleno", "Salvo que la convocatoria prevea otra cosa", "En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que lo solicite el tribunal"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('aux-age:16-933bac029d','aux-age',16,'La Delegación del Gobierno contra la Violencia de Género, entre otras funciones:','["Dicta resoluciones vinculantes para los juzgados de violencia sobre la mujer", "Dirige y coordina a la policía judicial en las investigaciones de violencia de género y dicta instrucciones a los juzgados especializados", "Elabora la Macroencuesta de Violencia contra las Mujeres y está legitimada ante los órganos jurisdiccionales", "Impone sanciones administrativas a los agresores y dirige las investigaciones de la policía judicial en los casos más graves"]'::jsonb,2,'Art. 29 LO 1/2004','Formula las políticas públicas en materia de violencia de género.',null),
('aux-age:16-acea8013c5','aux-age',16,'Entre los criterios de actuación de las Administraciones en el empleo público, la LO 3/2007 incluye:','["Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración", "Suprimir los planes de igualdad", "Establecer cuotas obligatorias del 60 % de mujeres en todos los órganos de selección y valoración", "Reservar los puestos directivos a la persona más antigua"]'::jsonb,0,'Art. 51 d) LO 3/2007','También establecer medidas efectivas para eliminar cualquier discriminación retributiva.',null),
('aux-age:11-887f581903','aux-age',11,'La cuestión de ilegalidad se plantea por el juez o tribunal mediante auto que deberá dictarse:','["Antes de dictar sentencia, dentro del plazo para dictarla y previa audiencia de las partes por diez días", "En el plazo de un mes desde la firmeza de la sentencia", "Dentro de los cinco días siguientes a que conste en las actuaciones la firmeza de la sentencia", "En el plazo de dos meses"]'::jsonb,2,'Art. 123.1 Ley 29/1998','Se plantea en cinco días desde la firmeza de la sentencia.',null),
('aux-age:16-7304873152','aux-age',16,'En los procedimientos (no penales) en que se aleguen actuaciones discriminatorias por razón de sexo, corresponde probar la ausencia de discriminación a:','["La persona demandante", "El Ministerio Fiscal", "La persona demandada", "El juez"]'::jsonb,2,'Art. 13.1 LO 3/2007','Es la inversión de la carga de la prueba; no se aplica a los procesos penales.',null),
('aux-age:13-18bfe4c11f','aux-age',13,'La excedencia por cuidado de un familiar hasta el segundo grado que no pueda valerse por sí mismo tiene una duración no superior a:','["Tres años", "Dos años", "Cinco años", "Un año"]'::jsonb,0,'Art. 89.4 TREBEP','Igual que la excedencia por cuidado de cada hijo.',null),
('aux-age:14-e323f46a9f','aux-age',14,'Si la incapacidad temporal impide disfrutar las vacaciones en el año natural, podrán disfrutarse una vez finalizada, siempre que no hayan transcurrido más de:','["Un año a partir del final del año en que se hayan originado", "Tres años", "Seis meses a partir del final del año en que se hayan originado", "Dieciocho meses a partir del final del año en que se hayan originado"]'::jsonb,3,'Art. 50.2 TREBEP','Las vacaciones no pueden sustituirse por una cuantía económica, salvo cese no voluntario.',null),
('aux-age:14-98726e3cec','aux-age',14,'En el permiso por nacimiento, ¿cuántas semanas inmediatas posteriores al parto son de descanso obligatorio?','["Dos semanas", "Seis semanas", "Diez semanas", "Cuatro semanas"]'::jsonb,1,'Art. 49 a) TREBEP','Las seis semanas posteriores al parto son obligatorias e ininterrumpidas.',null),
('aux-age:11-5bf8d8296e','aux-age',11,'La Sala de lo Contencioso-administrativo de la Audiencia Nacional conoce en única instancia de los recursos contra:','["Los actos de los Ayuntamientos de municipios de gran población", "Los actos del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y del Consejo General del Poder Judicial, en todo caso", "Las disposiciones generales y los actos de los Ministros y Secretarios de Estado, en los términos del art. 11", "Las sentencias de los TSJ"]'::jsonb,2,'Art. 11.1 a) Ley 29/1998','También conoce de las apelaciones contra resoluciones de los Juzgados Centrales. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('aux-age:11-20fc8ebfc3','aux-age',11,'En el procedimiento para la protección de los derechos fundamentales, la sentencia se dictará en el plazo de:','["Diez días desde que las actuaciones queden conclusas", "Un mes", "Veinte días desde la contestación", "Cinco días desde que las actuaciones queden conclusas"]'::jsonb,3,'Art. 121.1 Ley 29/1998','Es un procedimiento preferente y sumario.',null),
('aux-age:14-d4a44ff733','aux-age',14,'Es una falta muy grave según el art. 95.2 TREBEP:','["El descuido leve en el trabajo", "El abandono del servicio", "La falta de puntualidad ocasional", "Un retraso de diez minutos"]'::jsonb,1,'Art. 95.2 c) TREBEP','Otras faltas muy graves: desobediencia abierta, acoso laboral, etc.',null),
('aux-age:11-cfc8fd33f5','aux-age',11,'En la imposición de costas, la cantidad a satisfacer no podrá exceder de:','["6.000 euros por cada parte", "La cuantía total del proceso", "La mitad de la cuantía del proceso, salvo circunstancias que lo justifiquen", "La tercera parte de la cuantía del proceso, salvo circunstancias que lo justifiquen"]'::jsonb,3,'Art. 139.4 Ley 29/1998','Las pretensiones de cuantía indeterminada se valoran en 18.000 euros a estos efectos.',null),
